export function planar(p,t,lane,out=[0,0,0]){
 const phase=p.phase;
 const q=t+.10*Math.sin(t+phase)+.055*p.air*Math.sin(2*t-phase);
 const contour=.24*Math.sin(2*q+phase)+.17*Math.sin(3*q-phase);
 const depth=lane+.055*Math.sin(lane*TAU+phase)*Math.sin(Math.PI*lane);
 const span=.46+.10*p.air+.07*(1-p.brightness);
 const fan=.68+.32*(.5+.5*Math.sin(3*q+phase));
 const r=1.98+.08*(1-p.pitch)+contour-depth*span*fan;
 const turn=q+.025*Math.sin(2*t+phase);
 out[0]=Math.cos(turn)*r;out[2]=Math.sin(turn)*r;
 out[1]=.028+.022*Math.sin(3*t+phase)+.004*(lane-.5)*2*Math.sin(3*q+phase);
 return out;
}

export function planar(p,t,lane,out=[0,0,0]){
 const phase=p.phase;
 const q=t+.10*Math.sin(t+phase)+.055*p.air*Math.sin(2*t-phase);
 const contour=.16*Math.sin(2*q+phase)+.34*Math.sin(3*q-phase)+.06*p.air*Math.sin(5*q+phase);
 const depth=lane+.055*Math.sin(lane*TAU+phase)*Math.sin(Math.PI*lane);
 const span=.77+.10*p.air+.07*(1-p.brightness);
 const fan=.26+.74*(.5+.5*Math.sin(3*q+phase));
 const r=1.98+.08*(1-p.pitch)+contour-depth*span*fan;
 const turn=q+.025*Math.sin(2*t+phase)+.15*depth*Math.sin(3*q-phase);
 out[0]=Math.cos(turn)*r;out[2]=Math.sin(turn)*r;
 out[1]=.028+.022*Math.sin(3*t+phase)+.004*(lane-.5)*2*Math.sin(3*q+phase);
 return out;
}
